; -------------------------------------------------------------------------
; Sonic CD Disassembly - Mega Drive port
; -------------------------------------------------------------------------
; Standalone Mega Drive ROM: Stardust Speedway Act 2 (R72D) - generated by tools/mmd2md
; -------------------------------------------------------------------------
; Build from the "src" folder (see build_md.sh). Everything Sega CD specific
; in the level code is switched off with "if def(MDPORT)".
; -------------------------------------------------------------------------

	if def(MDPORT)=0
MDPORT		EQU	1				; Mega Drive port build flag (build_md.sh also passes it)
	endif

	include	"Level/_Definitions.inc"		; Hardware definitions, RAM map and macros (included once)

; -------------------------------------------------------------------------
; RAM used by the port (all in the hole $FFFFB000-$FFFFC7FF of the level's map)
; -------------------------------------------------------------------------
;   $FFFFB000-$FFFFBFFF  Time warp cutscene variables (MD Port/Time Warp/Main.asm)
;   $FFFFC000-$FFFFC7FF  Level data the Sega CD build kept inside its (RAM-resident)
;                        code, which is read-only on a cartridge:
debugSpeed	EQU	$FFFFC000		; Debug mode speed (long)

; -------------------------------------------------------------------------
; Vector table
; -------------------------------------------------------------------------

Vectors:
	dc.l	$01000000				; Initial stack pointer (top of Work RAM, ~1KB free above the level RAM)
	dc.l	EntryPoint				; Reset
	dc.l	ErrorTrap				; Bus error
	dc.l	ErrorTrap				; Address error
	dc.l	ErrorTrap				; Illegal instruction
	dc.l	ErrorTrap				; Division by zero
	dc.l	ErrorTrap				; CHK exception
	dc.l	ErrorTrap				; TRAPV exception
	dc.l	ErrorTrap				; Privilege violation
	dc.l	ErrorTrap				; TRACE exception
	dc.l	ErrorTrap				; Line-A emulator
	dc.l	ErrorTrap				; Line-F emulator
	rept	12						; Reserved
		dc.l	ErrorTrap
	endr
	dc.l	ErrorTrap				; Spurious interrupt
	dc.l	ErrorTrap				; IRQ level 1
	dc.l	ErrorTrap				; IRQ level 2
	dc.l	ErrorTrap				; IRQ level 3
	dc.l	JmpTo_HInt				; IRQ level 4 (H-INT)
	dc.l	ErrorTrap				; IRQ level 5
	dc.l	MDVInt				; IRQ level 6 (V-INT, through the RAM jump at _LEVEL6)
	dc.l	ErrorTrap				; IRQ level 7
	rept	16						; TRAP #00-#15
		dc.l	ErrorTrap
	endr
	rept	16						; Reserved
		dc.l	ErrorTrap
	endr

; -------------------------------------------------------------------------
; ROM header
; -------------------------------------------------------------------------

	dc.b	"SEGA MEGA DRIVE "			; Hardware ID
	dc.b	"(C)SCDM 2026.OCT"			; Release date
	dc.b	"SONIC THE HEDGEHOG CD (MEGA DRIVE PORT)"
	dcb.b	$150-*,$20				; Domestic name
	dc.b	"SONIC THE HEDGEHOG CD (MEGA DRIVE PORT)"
	dcb.b	$180-*,$20				; Overseas name
	dc.b	"GM 00000000-00"			; Serial number
	dc.w	0						; Checksum (fixed by build_md.sh)
	dc.b	"J"						; I/O support (3-button pad)
	dcb.b	$1A0-*,$20
	dc.l	0						; ROM start
	dc.l	ROMEnd-1				; ROM end
	dc.l	$FF0000,$FFFFFF			; RAM start/end
	dcb.b	$1F0-*,$20				; No SRAM, no modem, no notes
	dc.b	"JUE"					; Region
	dcb.b	$200-*,$20

; -------------------------------------------------------------------------
; Entry point
; -------------------------------------------------------------------------
; NOTE: nothing before the RAM clear may use the stack (no bsr/jsr).
; Hardware and RAM are always fully re-initialized, including on a soft reset:
; the level relies on clean RAM (initFlag, fade/PLC flags...).
; -------------------------------------------------------------------------

EntryPoint:
	move.b	VERSION,d0				; TMSS handshake (only on consoles that have it)
	andi.b	#$0F,d0
	beq.s	.NoTMSS
	move.l	#'SEGA',TMSSSEGA

.NoTMSS:
	move.w	VDPCTRL,d0				; Clear any pending VDP command

	; Z80: stop it, reset it, and park it on a harmless "di / jp 0" loop
	move.w	#$100,Z80BUS
	move.w	#$100,Z80RESET
.WaitZ80:
	btst	#0,Z80BUS
	bne.s	.WaitZ80
	lea	Z80RAM,a0
	move.b	#$F3,(a0)+				; di
	move.b	#$F3,(a0)+				; di
	move.b	#$C3,(a0)+				; jp $0000
	move.b	#0,(a0)+
	move.b	#0,(a0)+
	move.w	#0,Z80RESET				; Z80 reset on
	moveq	#$7F,d0					; Short delay
	dbf	d0,*
	move.w	#0,Z80BUS				; Give the bus back
	move.w	#$100,Z80RESET			; Z80 reset off (it now runs the loop)

	; Silence the PSG
	lea	PSGCTRL,a0
	move.b	#$9F,(a0)
	move.b	#$BF,(a0)
	move.b	#$DF,(a0)
	move.b	#$FF,(a0)

	; Clear all Work RAM
	moveq	#0,d0
	lea	WORKRAME,a6
	move.w	#WORKRAMS/4-1,d6
.ClearRAM:
	move.l	d0,-(a6)
	dbf	d6,.ClearRAM

	; VDP registers
	lea	MDVDPRegs(pc),a0
	move.w	#$8000,d0
	moveq	#MDVDPRegsEnd-MDVDPRegs-1,d7
.SetupVDP:
	move.b	(a0)+,d0
	move.w	d0,VDPCTRL
	addi.w	#$100,d0
	dbf	d7,.SetupVDP

	; Controller ports
	moveq	#$40,d0
	move.b	d0,IOCTRL1
	move.b	d0,IOCTRL2
	move.b	d0,IOCTRL3
	move.b	#$C0,IODATA1

	; Clear VRAM, CRAM and VSRAM
	move.l	#$40000000,VDPCTRL
	lea	VDPDATA,a0
	moveq	#0,d0
	move.w	#$10000/16-1,d7
.ClearVRAM:
	rept	16/4
		move.l	d0,(a0)
	endr
	dbf	d7,.ClearVRAM

	move.l	#$C0000000,VDPCTRL
	moveq	#$80/4-1,d7
.ClearCRAM:
	move.l	d0,(a0)
	dbf	d7,.ClearCRAM

	move.l	#$40000010,VDPCTRL
	moveq	#$50/4-1,d7
.ClearVSRAM:
	move.l	d0,(a0)
	dbf	d7,.ClearVSRAM

	move.w	#$4EF9,_LEVEL6.w			; Install the RAM V-INT jump (like the Sega CD BIOS did)
	move.l	#JmpTo_VInt,_LEVEL6+2.w

.InitDone:
	move	#$2700,sr				; Interrupts off until the level enables them
	movea.l	(Vectors).l,sp			; Reset the stack pointer (also on soft reset)

; -------------------------------------------------------------------------
; Main loop (replaces what the Sega CD IPX did around RunLevel)
; -------------------------------------------------------------------------

MDMain:
	bsr.s	MDResetGame
	if def(MDWARPTEST)
		jsr	TimeWarpCutscene			; (dev switch) show the time warp screen first
		move.b	#TIME_FUTURE|$80,timeZone	; ...and come back the way the real warp flow does
	endif				; Same state the IPX leaves before starting a new game

.RunLevel:
	jsr	Start					; Run the level; returns when the level is over
	movea.l	(Vectors).l,sp			; (just in case the level left junk on the stack)

	tst.b	lives					; Out of lives?
	bne.s	.NotGameOver			; If not, branch
	bsr.s	MDResetGame				; Game over: start a new game
	bra.s	.RunLevel

.NotGameOver:
	btst	#7,timeZone			; Time warping?
	beq.s	.Replay				; If not, branch

	jsr	TimeWarpCutscene			; Run the time warp cutscene (game mode ported from Time Warp Cutscene/)

	; TODO (phase 2): pick R11B/R11C/R11D from timeZone and goodFuture, like the
	; IPX did. Until the other time zones are in the ROM we come back to the
	; present (bit 7 stays set so the level fades in from white).
	move.b	#TIME_FUTURE|$80,timeZone
	bra.s	.RunLevel

.Replay:
	bclr	#7,timeZone			; Plain level end: replay the present
	bra.s	.RunLevel

; -------------------------------------------------------------------------
; V-INT trampoline: the real handler is whatever the RAM jump at _LEVEL6 says
; -------------------------------------------------------------------------

MDVInt:
	jmp	_LEVEL6.w

; -------------------------------------------------------------------------
; Reset game state (mirrors CD Initial Program/IPX.asm .GameLoop)
; -------------------------------------------------------------------------

MDResetGame:
	moveq	#0,d0
	move.l	d0,score
	move.b	d0,timeAttackMode
	move.b	d0,specialStage
	move.b	d0,checkpoint
	move.w	d0,rings
	move.l	d0,time
	move.b	d0,goodFuture
	move.b	d0,projDestroyed
	move.b	d0,plcLoadFlags
	move.b	#TIME_FUTURE,timeZone
	move.b	#0,goodFuture
	move.w	#$0501,zoneAct			; Stardust Speedway, act 2 (the level engine dispatches by zone)
	rts

; -------------------------------------------------------------------------
; Initial VDP register values (same as MDINIT.MMD)
; -------------------------------------------------------------------------

MDVDPRegs:
	dc.b	%00000100				; No H-INT
	dc.b	%00110100				; V-INT, DMA, mode 5
	dc.b	$C000/$400				; Plane A location
	dc.b	0					; Window location
	dc.b	$C000/$2000				; Plane B location
	dc.b	$E000/$200				; Sprite table location
	dc.b	0					; Reserved
	dc.b	0					; BG color
	dc.b	0					; Reserved
	dc.b	0					; Reserved
	dc.b	0					; H-INT counter
	dc.b	%00000000				; Scroll by screen
	dc.b	%10000001				; H40
	dc.b	$E400/$400				; Horizontal scroll table location
	dc.b	0					; Reserved
	dc.b	2					; Auto increment by 2
	dc.b	%00000001				; 64x32 tile plane size
	dc.b	0					; Window horizontal position
	dc.b	0					; Window vertical position
MDVDPRegsEnd:
	even

; -------------------------------------------------------------------------
; The level (code + data, all in ROM)
; -------------------------------------------------------------------------

	include	"Level/Stardust Speedway/Act 2 Bad Future.asm"

; -------------------------------------------------------------------------
; Time warp cutscene game mode (ported from "Time Warp Cutscene/")
; -------------------------------------------------------------------------

	include	"MD Port/Time Warp/Main.asm"

	ALIGN	$20000, $FF				; Pad ROM to a multiple of 128KB
ROMEnd:
